import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a daily scheduled trigger at a specific time.

Flow(
    {
        $id: Now.ID['flow_trigger_scheduled_daily'],
        name: 'Flow - Trigger Scheduled Daily',
        description: 'Flow used by tests to validate daily scheduled trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.scheduled.daily,
        { $id: Now.ID['trigger_scheduled_daily'], annotation: 'Daily scheduled trigger at 01:00:00' },
        {
            time: Time({ hours: 1, minutes: 0, seconds: 0 }),
        }
    ),
    () => {
        // Empty body; this test focuses on scheduled trigger configuration only
    }
)
